{
  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [["excel_file", "file"]]
      }
    },
    {
      "id": "2",
      "type": "document-extractor",
      "param": {
        "variable_selector": ["excel_file", "1"]
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [["extracted_text", ["text", "2"]]],
        "outputs": [["result", "string"]],
        "code": "def main(extracted_text: str):
	import json

	try:
		# Split into lines and filter out empty lines
		lines = [line.strip() for line in extracted_text.split('\n') if line.strip()]

		if not lines:
			return {"result": "[]"}

		# Assume first row is header
		headers = lines[0].split('\t')

		# If no tabs found, try comma
		if len(headers) == 1:
			headers = lines[0].split(',')

		# Clean headers
		headers = [h.strip() for h in headers if h.strip()]

		if not headers:
			return {"result": "[]"}

		# Process data rows
		data = []
		for line in lines[1:]:
			values = line.split('\t')
			if len(values) == 1:
				values = line.split(',')

			values = [v.strip() for v in values]

			# Only add if we have values
			if values and any(values):
				row_dict = {}
				for i, header in enumerate(headers):
					if i < len(values):
						# Handle empty cells
						row_dict[header] = values[i] if values[i] else ""
				data.append(row_dict)

		# Convert to JSON string
		json_result = json.dumps(data, ensure_ascii=False, indent=2)

		return {"result": json_result}

	except Exception as e:
		return {"result": json.dumps({"error": str(e)}, ensure_ascii=False)}"
      }
    },
    {
      "id": "4",
      "type": "end",
